    final ShrinkerThread<String, String> shrinker = new ShrinkerThread<>( cache );
    shrinker.run();

    Thread.sleep( 500 );
    assertEquals( "Waterfall called the wrong number of times.", 3, memory.waterfallCallCount );
}

mut_docstring:
/**
         * Main processing method for the AbstractCacheEvent object
         */

mut_method_definition:
@Override
        public void run()
        {
            for (int failures = 0; failures < maxFailure; failures++)
            {
                try
                {
                    doRun();
                    return;
                }
                catch (final IOException e)
                {
                    log.warn("Error while running event from Queue: {0}. "
                            + "Retrying...", this, e);
                }

                try
                {
                    Thread.sleep( waitBeforeRetry );
                }
                catch ( final InterruptedException ie )
                {
                    log.warn("Interrupted while sleeping for retry on event "
                            + "{0}.", this, ie);
                    break;
                }
            }

            log.warn( "Dropping Event and marking Event Queue {0} as "
                    + "non-functional.", this );
            destroy();
        }

